// ---- local TTS playback ---------------------------------------------------

/** The translation plugin hosts the same Edge neural / macOS voices we use. */
const TRANSLATE_API = '/dsh-translate/api'
const VOICE_PREVIEW_TEXT = 'This is how your English will sound.'
/** Same labels and order as the translation panel. */
const SPEECH_RATE_OPTIONS = [
  { value: 100, label: '慢' },
  { value: 140, label: '稍慢' },
  { value: 165, label: '正常' },
  { value: 190, label: '快' },
]
/** Used when the translation plugin is disabled, so the picker stays usable. */
const FALLBACK_VOICES = [
  { name: 'Samantha', label: 'Samantha · 本机', value: 'say:Samantha', provider: 'say' },
  { name: 'Daniel', label: 'Daniel · 本机', value: 'say:Daniel', provider: 'say' },
  { name: '浏览器', label: '浏览器内置语音', value: 'browser:', provider: 'browser' },
]

let ttsInfoCache
let ttsInfoPending

/** Voice list + engine status, read from the translation plugin when it is on. */
function fetchTtsInfo() {
  if (ttsInfoCache !== undefined) return Promise.resolve(ttsInfoCache)
  if (ttsInfoPending !== undefined) return ttsInfoPending
  ttsInfoPending = fetch(`${TRANSLATE_API}/info`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: '{}',
  })
    .then((response) => (response.ok ? response.json() : null))
    .then((data) => {
      const info = data !== null && typeof data === 'object' ? data.tts : null
      const usable = info !== null && typeof info === 'object' && Array.isArray(info.voices) && info.voices.length > 0
      // Only a real answer is cached; a miss is retried the next time the menu mounts.
      ttsInfoCache = usable ? info : undefined
      ttsInfoPending = undefined
      return usable ? info : null
    })
    .catch(() => {
      ttsInfoPending = undefined
      ttsInfoCache = undefined
      return null
    })
  return ttsInfoPending
}

function useTtsInfo() {
  const [state, setState] = useState(() => ({ info: ttsInfoCache ?? null, loading: ttsInfoCache === undefined }))
  useEffect(() => {
    let alive = true
    fetchTtsInfo().then((info) => {
      if (alive) setState({ info, loading: false })
    })
    return () => {
      alive = false
    }
  }, [])
  return state
}

/**
 * Render one clip to a playable blob URL. The translation plugin serves the
 * shared Edge/本机 voices; the NCE host `say` route is the offline fallback.
 */
async function fetchAudioUrl(text, voice, rate) {
  try {
    const response = await fetch(`${TRANSLATE_API}/tts`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ text, voice, rate }),
    })
    if (response.ok) return URL.createObjectURL(await response.blob())
  } catch {
    // Fall through to the local voice.
  }
  try {
    const response = await fetch(`${API_BASE}/tts`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ text, rate }),
    })
    if (response.ok) return URL.createObjectURL(await response.blob())
  } catch {
    // The browser voice is the last resort.
  }
  return null
}

const audioState = { playing: false, text: '' }
const audioListeners = new Set()
const audioCache = new Map()
let audioElement = null

function emitAudio() {
  const snapshot = { playing: audioState.playing, text: audioState.text }
  for (const listener of audioListeners) {
    try {
      listener(snapshot)
    } catch {
      // Keep the other listeners alive.
    }
  }
}

function setAudioState(playing, text) {
  audioState.playing = playing
  audioState.text = playing ? String(text ?? '') : ''
  emitAudio()
}

function audioElementOf() {
  if (audioElement !== null) return audioElement
  const element = new Audio()
  element.preload = 'auto'
  element.addEventListener('ended', () => setAudioState(false, ''))
  element.addEventListener('error', () => setAudioState(false, ''))
  audioElement = element
  return element
}

function stopSpeech() {
  if (typeof window !== 'undefined' && window.speechSynthesis !== undefined) {
    try {
      window.speechSynthesis.cancel()
    } catch {
      // Best effort.
    }
  }
  if (audioElement !== null) {
    try {
      audioElement.pause()
      audioElement.currentTime = 0
    } catch {
      // Best effort.
    }
  }
  setAudioState(false, '')
}

function speakWithBrowser(text) {
  if (typeof window === 'undefined' || window.speechSynthesis === undefined) return false
  try {
    const utterance = new window.SpeechSynthesisUtterance(text)
    utterance.lang = 'en-US'
    utterance.rate = 0.95
    utterance.onend = () => setAudioState(false, '')
    utterance.onerror = () => setAudioState(false, '')
    window.speechSynthesis.cancel()
    window.speechSynthesis.speak(utterance)
    setAudioState(true, text)
    return true
  } catch {
    setAudioState(false, '')
    return false
  }
}

/**
 * Speak one English word/sentence through the same voice pipeline as the
 * translation panel (Edge neural voices, macOS voices as fallback); the Web
 * Speech API is only used when both hosts are unavailable.
 */
async function playText(text, options) {
  const value = String(text ?? '').trim()
  if (value === '') return
  const trimmed = value.length > 280 ? value.slice(0, 280) : value
  const prefs = readPrefs()
  const rate = options?.rate ?? prefs.rate
  const voice = options?.voice ?? prefs.voice
  const cacheKey = `${voice}\u0000${rate}\u0000${trimmed}`
  stopSpeech()
  try {
    let url = audioCache.get(cacheKey)
    if (url === undefined) {
      url = await fetchAudioUrl(trimmed, voice, rate)
      if (url === null) throw new Error('tts unavailable')
      if (audioCache.size >= 120) {
        const first = audioCache.keys().next().value
        const stale = audioCache.get(first)
        audioCache.delete(first)
        try {
          URL.revokeObjectURL(stale)
        } catch {
          // Best effort.
        }
      }
      audioCache.set(cacheKey, url)
    }
    const element = audioElementOf()
    element.src = url
    setAudioState(true, trimmed)
    await element.play().catch(() => {
      setAudioState(false, '')
      throw new Error('playback blocked')
    })
  } catch (error) {
    if (!speakWithBrowser(trimmed)) setAudioState(false, '')
    else if (isAbortError(error)) setAudioState(false, '')
  }
}

function useSpeaking() {
  const [snapshot, setSnapshot] = useState(() => ({ playing: audioState.playing, text: audioState.text }))
  useEffect(() => {
    audioListeners.add(setSnapshot)
    return () => {
      audioListeners.delete(setSnapshot)
    }
  }, [])
  return snapshot
}

  // ---------------------------------------------------------------------
  // 05-data.js
  // ---------------------------------------------------------------------
// Layer: 05 data — depends on: 00-platform (hooks) and 03-api (`api`).
// Module-cached data hooks: one request per host resource, shared by every view.

// ---- data hooks (module-level cache, one request per resource) ------------

const remoteCache = new Map()

function useRemote(operation) {
  const [state, setState] = useState(() => remoteCache.has(operation)
    ? { data: remoteCache.get(operation), loading: false, error: null }
    : { data: null, loading: true, error: null })
  const [tick, setTick] = useState(0)
  useEffect(() => {
    if (state.data !== null && tick === 0) return undefined
    let alive = true
    setState((previous) => ({ data: previous.data, loading: true, error: null }))
    api(operation)
      .then((result) => {
        remoteCache.set(operation, result)
        if (alive) setState({ data: result, loading: false, error: null })
      })
      .catch((error) => {
        if (alive) setState({ data: null, loading: false, error })
      })
    return () => {
      alive = false
    }
  }, [operation, tick])
  const reload = useCallback(() => {
    remoteCache.delete(operation)
    setTick((value) => value + 1)
  }, [operation])
  return { ...state, reload }
}

function useIndex() {
  return useRemote('index')
}

function useWordbank() {
  return useRemote('wordbank')
}

function usePhonetics() {
  return useRemote('phonetics')
}

const lessonCache = new Map()

function useLesson(id) {
  const valid = Number.isInteger(id) && id > 0
  const [state, setState] = useState(() => (valid && lessonCache.has(id)
    ? { data: lessonCache.get(id), loading: false, error: null }
    : { data: null, loading: valid, error: null }))
  const [tick, setTick] = useState(0)
  useEffect(() => {
    if (!valid) {
      setState({ data: null, loading: false, error: null })
      return undefined
    }
    if (lessonCache.has(id) && tick === 0) {
      setState({ data: lessonCache.get(id), loading: false, error: null })
      return undefined
    }
    let alive = true
    setState({ data: lessonCache.get(id) ?? null, loading: true, error: null })
    api('lesson', { id })
      .then((result) => {
        lessonCache.set(id, result.lesson)
        if (alive) setState({ data: result.lesson, loading: false, error: null })
      })
      .catch((error) => {
        if (alive) setState({ data: null, loading: false, error })
      })
    return () => {
      alive = false
    }
  }, [id, valid, tick])
  const reload = useCallback(() => {
    if (!valid) return
    lessonCache.delete(id)
    setTick((value) => value + 1)
  }, [id, valid])
  return { ...state, reload }
}

  // ---------------------------------------------------------------------
  // 06-store.js
  // ---------------------------------------------------------------------
// Layer: 06 store — depends on: 00-platform (hooks), 02-persistence (`readNav`/`writeNav`), 03-api (`api`).
// The learning store: nav state, progress, lesson updates, word grading and video saving.

// ---- learning store -------------------------------------------------------

const NceContext = React.createContext(null)

function NceProvider(props) {
  const [nav, setNav] = useState(readNav)
  const [progress, setProgress] = useState(null)
  const [progressError, setProgressError] = useState(null)

  const loadProgress = useCallback((signal) => {
    api('progress', {}, { signal })
      .then((result) => {
        setProgress(result.progress)
      })
      .catch((error) => {
        if (!isAbortError(error)) setProgressError(error)
      })
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    loadProgress(controller.signal)
    return () => controller.abort()
  }, [loadProgress])

  useEffect(() => {
    writeNav(nav)
  }, [nav])

  const go = useCallback((page, params) => {
    setNav((previous) => ({ ...previous, page, ...(params ?? {}) }))
  }, [])

  /** Selecting a lesson keeps the 课程 tab active (left list + right detail). */
  const openLesson = useCallback((id, tab) => {
    setNav({ page: 'home', lessonId: id, tab: tab ?? '' })
  }, [])

  /** Consume a one-shot lesson anchor (`nav.tab`) once the lesson page used it. */
  const clearLessonTab = useCallback(() => {
    setNav((previous) => (previous.tab === '' ? previous : { ...previous, tab: '' }))
  }, [])

  const updateLesson = useCallback(async (id, patch) => {
    const result = await api('lesson/status', { id, ...(patch ?? {}) })
    if (result.progress !== undefined) setProgress(result.progress)
    return result.lesson
  }, [])

  const starWord = useCallback(async (key, starred) => {
    setProgress((previous) => {
      if (previous === null) return previous
      const words = { ...previous.words }
      const entry = { ...(words[key] ?? {}) }
      if (starred) entry.starred = true
      else delete entry.starred
      if (Object.keys(entry).length === 0) delete words[key]
      else words[key] = entry
      return { ...previous, words }
    })
    try {
      await api('word/star', { key, starred })
    } catch (error) {
      loadProgress()
      throw error
    }
  }, [loadProgress])

  /** Grade one word; returns the host's next card and updated streak. */
  const gradeWord = useCallback(async (key, grade) => {
    const result = await api('review/grade', { key, grade })
    setProgress((previous) => {
      if (previous === null) return previous
      const words = { ...previous.words }
      const entry = { ...(words[key] ?? {}) }
      entry.srs = result.card
      if (grade === 'again') entry.wrong = (Number(entry.wrong) || 0) + 1
      else if (grade !== 'hard') entry.right = (Number(entry.right) || 0) + 1
      words[key] = entry
      const history = { ...previous.history }
      const today = todayKey()
      history[today] = (Number(history[today]) || 0) + 1
      return { ...previous, words, history, streak: result.streak ?? previous.streak }
    })
    return result
  }, [])

  const saveVideo = useCallback(async (id, url) => {
    const result = await api('video/save', { id, url })
    return result.video
  }, [])

  const value = useMemo(() => ({
    nav,
    go,
    openLesson,
    clearLessonTab,
    progress,
    progressError,
    reloadProgress: () => loadProgress(),
    updateLesson,
    starWord,
    gradeWord,
    saveVideo,
  }), [nav, go, openLesson, clearLessonTab, progress, progressError, loadProgress, updateLesson, starWord, gradeWord, saveVideo])

  return h(NceContext.Provider, { value }, props.children)
}

function useNce() {
  const context = useContext(NceContext)
  if (context === null) throw new Error('useNce 必须在 NceProvider 内使用')
  return context
}

